INSERT INTO prompts (id, title, category, role, tags, access, prompt_body) SELECT id, title, 'Banking & Fintech Engagement', 'a senior banking and fintech customer-engagement strategist', tags, access, CONCAT('ROLE: You are a senior banking and fintech customer-engagement strategist with expertise in ', LOWER(tags), '.\n\nTASK: Create a production-ready ', LOWER(title), ' for [specific use-case] and [campaign goal].\n\nAUDIENCE: [target customer segment] with documented consent where required.\n\nPLATFORM / FORMAT: [preferred channel or format].\n\nTONE / VOICE: Clear, reassuring, inclusive, concise, and useful.\n\nPRIMARY GOAL: [campaign goal].\n\nDELIVERABLES:\n1. A ready-to-use sequence, brief, or engagement asset with clear variables.\n2. Personalization logic for [customer segment] and [customer stage].\n3. Timing, CTA, measurement, and human hand-off recommendations.\n4. Channel-specific copy for the tagged channels.\n5. Compliance review notes and an approval checklist.\n\nCONSTRAINTS: Use only consented outreach, minimize personal data, mask identifiers, never request full card numbers, PINs, PANs, or passwords, avoid guaranteed outcomes, include opt-out and HELP handling, use secure authenticated links for sensitive actions, and provide human escalation.') FROM (SELECT '3240' AS id, 'International transfer FAQ flow' AS title, 'Customer Service, WhatsApp, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3241' AS id, 'Cashback offer compliance brief' AS title, 'Marcom, Compliance, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3242' AS id, 'Referral campaign message matrix' AS title, 'Acquisition, SMS, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3243' AS id, 'Product comparison explainer video' AS title, 'AI Video, Marcom, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3244' AS id, 'Responsible lending content plan' AS title, 'Education, Compliance, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3245' AS id, 'Data privacy notice campaign' AS title, 'Compliance, SMS, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3246' AS id, 'Consent renewal journey' AS title, 'Compliance, Automation, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3247' AS id, 'Account security education series' AS title, 'Security, AI Video, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3248' AS id, 'Phishing awareness campaign' AS title, 'Security, Marcom, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3249' AS id, 'Payment holiday information flow' AS title, 'Collections, WhatsApp, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3250' AS id, 'Delinquency prevention journey' AS title, 'Collections, SMS, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3251' AS id, 'Credit limit review campaign' AS title, 'Lending, WhatsApp, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3252' AS id, 'Overdraft education sequence' AS title, 'Education, SMS, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3253' AS id, 'Open banking feature launch' AS title, 'Product Marketing, Marcom, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3254' AS id, 'API partner onboarding brief' AS title, 'Partnerships, Automation, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3255' AS id, 'Fintech product launch campaign' AS title, 'Marcom, AI Video, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3256' AS id, '30-day omnichannel retention plan' AS title, 'Marcom, WhatsApp, SMS, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3257' AS id, '30-day onboarding engagement plan' AS title, 'Marcom, WhatsApp, SMS, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3258' AS id, 'AI creative asset production plan' AS title, 'AI Video, Creative, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3259' AS id, 'Regulated campaign KPI dashboard' AS title, 'Analytics, Marcom, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3260' AS id, 'Compliance review checklist pack' AS title, 'Compliance, Banking, Fintech' AS tags, 'LOCKED' AS access) AS batch ON DUPLICATE KEY UPDATE title=VALUES(title), category=VALUES(category), role=VALUES(role), tags=VALUES(tags), access=VALUES(access), prompt_body=VALUES(prompt_body);\n